def acorn1_neighbors(v, nbrs, passes, M):
    out = []
    for u in nbrs[v]:              # one hop
        for w in [u] + nbrs[u]:    # u, then u's neighbors
            if w != v and w not in out and passes(w):
                out.append(w)
    return out[:M]                 # truncate to M

nbrs = {"H": ["G", "A", "I"], "G": ["H", "J"],
        "A": ["I", "H"], "I": ["A", "H"]}
passes = lambda x: x in {"B", "D", "H", "I", "J"}
print(acorn1_neighbors("H", nbrs, passes, M=2))
